public class JobMatcher
{
    public IEnumerable<JobPosting> MatchJobs(Profile profile)
    {
        var userSkills = profile.Skills.ToHashSet();
        return _jobs
            .Where(j => j.RequiredSkills.Any(s => userSkills.Contains(s)))
            .OrderByDescending(j => j.RequiredSkills.Count(s => userSkills.Contains(s)))
            .ThenByDescending(j => j.PostedAt);
    }
}

public class EndorsementService
{
    public void Endorse(Guid endorserId, Guid targetProfileId, string skill)
    {
        var key = (endorserId, targetProfileId, skill);
        if (_endorsements.ContainsKey(key)) return; // already endorsed
        _endorsements[key] = true;
        _profiles[targetProfileId].Skills.Add(skill);
    }

    public int GetEndorsementCount(Guid profileId, string skill)
    {
        return _endorsements.Count(kv => kv.Key.targetProfileId == profileId && kv.Key.skill == skill);
    }
}
